        deallocate();
        start = tmp;
        end_of_storage = start + xlen;
      }
      else if (size() >= xlen) {
        iterator i = copy(x.begin(), x.end(), begin());
        destroy(i, finish);
      }
      else {
        copy(x.begin(), x.begin() + size(), start);
        uninitialized_copy(x.begin() + size(), x.end(), finish, 0);
      }
      finish = start + xlen;
    }
    return *this;
  }
};

